local c=Vector3.new(23,9,-23) local o={}
for _,d in workspace.Plaza:GetDescendants() do if d:IsA('BasePart') and d.Transparency<1 and (d.Position-c).Magnitude<9 and d.Size.Magnitude<40 then table.insert(o,d:GetFullName():gsub('Workspace.Plaza.','')..' '..d.ClassName..' '..d.Material.Name..' '..string.format('(%d,%d,%d)',d.Color.R*255,d.Color.G*255,d.Color.B*255)..' sz '..string.format('%.1f,%.1f,%.1f',d.Size.X,d.Size.Y,d.Size.Z)..' at '..string.format('%.1f,%.1f,%.1f',d.Position.X,d.Position.Y,d.Position.Z)) end end
for _,d in workspace.Plaza:GetDescendants() do if (d:IsA('PointLight') or d:IsA('SpotLight') or d:IsA('SurfaceLight')) and d.Parent:IsA('BasePart') and (d.Parent.Position-c).Magnitude<12 then table.insert(o,'LIGHT '..d:GetFullName():gsub('Workspace.Plaza.','')..' '..tostring(d.Color)..' b'..d.Brightness..' r'..d.Range..' en '..tostring(d.Enabled)) end end
return table.concat(o,'\n')
